UserObject.plantUmlData:
{
  "data": "@startuml
skinparam Style strictuml

title Admin Activity Diagram - Inventory Management & Today's Offer

start
:Admin opens Admin Sign-In Page;
:Admin inputs Email and Password;

if (Validate Credentials?) then (Valid)
  :System authenticates session;
  :System displays Admin Dashboard;
else (Invalid)
  :System displays error "Invalid credentials";
  stop
endif

repeat
  :Admin views Inventory List;

  if (Select Action) then (Add New Item)
    :Admin fills in Motorcycle Details (Brand, Model, Year, Price, Mileage);
    :Admin uploads vehicle photo;
    :Admin clicks "Save Item";
    if (All required fields filled?) then (Yes)
      :System stores new record in Database;
      :System shows "Item added successfully";
    else (No)
      :System highlights missing fields;
    endif

  elseif (Select Action) then (Update / Edit Item)
    :Admin modifies existing Motorcycle specs/status;
    :Admin saves changes;
    :System updates Database record;

  elseif (Select Action) then (Toggle Today's Offer)
    :Admin enables "Today's Offer" toggle for selected item;
    :System updates promotion status in Database;
    :System reflects promotion on Customer Landing Page;

  else (Delete Item)
    :Admin selects item to remove;
    :System prompts confirmation;
    :Admin confirms deletion;
    :System removes record from Database;
  endif

repeat while (Admin continues managing inventory?) is (Yes)
->No;

:Admin clicks Logout;
:System terminates session;
stop
@enduml
@enduml",
  "config": null
}
